import{_ as o,o as a,c as r,ag as n}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"04 趋势预测合集（24篇）精读笔记","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/04_趋势预测合集.md","filePath":"topics/tianya/notes/04_趋势预测合集.md"}'),e={name:"topics/tianya/notes/04_趋势预测合集.md"};function s(u,t,q,h,i,l){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_04-趋势预测合集-24篇-精读笔记" tabindex="-1">04 趋势预测合集（24篇）精读笔记 <a class="header-anchor" href="#_04-趋势预测合集-24篇-精读笔记" aria-label="Permalink to &quot;04 趋势预测合集（24篇）精读笔记&quot;">​</a></h1><blockquote><p>文本来源：/tmp/thunder/texts/（24 个 txt）。&quot;→2026现实检验&quot;以 2026 年视角回看；回帖噪音已剔除，只取楼主正文。</p></blockquote><hr><h2 id="一、货币政策与汇率类" tabindex="-1">一、货币政策与汇率类 <a class="header-anchor" href="#一、货币政策与汇率类" aria-label="Permalink to &quot;一、货币政策与汇率类&quot;">​</a></h2><h3 id="_1-《中国会跟随美联储加息吗-》-金乐福-2018-09–11" tabindex="-1">1.《中国会跟随美联储加息吗？》（金乐福，2018.09–11） <a class="header-anchor" href="#_1-《中国会跟随美联储加息吗-》-金乐福-2018-09–11" aria-label="Permalink to &quot;1.《中国会跟随美联储加息吗？》（金乐福，2018.09–11）&quot;">​</a></h3><p><strong>核心论点</strong>：①美联储加息意在为下轮衰退储备弹药；②中国要降实体融资成本，不会跟随加息，反而降准对冲（&quot;挤牙膏式宽松&quot;）；③A 股估值已基本合理，冲击有限。 <strong>金句</strong>：「你知道债务有多重吗？」 <strong>→2026 检验：准。</strong> 2018 年 10 月即降准 7500 亿；此后基准利率从未上调，一路降准降息至 2025；人民币破 7 但未失控。属同期少见的明确且正确判断。</p><h3 id="_2-《所有跌入中等收入陷阱的国家都源自持续性的贬值本币-》-样条曲线a-2019-10" tabindex="-1">2.《所有跌入中等收入陷阱的国家都源自持续性的贬值本币！》（样条曲线A，2019.10） <a class="header-anchor" href="#_2-《所有跌入中等收入陷阱的国家都源自持续性的贬值本币-》-样条曲线a-2019-10" aria-label="Permalink to &quot;2.《所有跌入中等收入陷阱的国家都源自持续性的贬值本币！》（样条曲线A，2019.10）&quot;">​</a></h3><p><strong>核心论点</strong>：①以俄、哈、巴西、土耳其、马来西亚为例：本币对美元贬值恰好吃掉本币计价的全部增长，美元口径 GDP 停滞即&quot;中等收入陷阱&quot;；②中国唯一出路是人民币大幅升值（甚至到 3）。 <strong>→2026 检验：部分准，药方错。</strong> 现象有洞见：中国人均美元 GDP 在 1.25 万美元附近多年徘徊，确有&quot;美元口径停滞&quot;之像；但中国并未升值，RMB 反在 7.1–7.3，且 2023 年后停滞主因是内需与地产而非汇率。</p><h3 id="_3-《黄金价格这么个玩法-意味着国际性大通胀时代的降临》-高天无影1-2019-08–11" tabindex="-1">3.《黄金价格这么个玩法，意味着国际性大通胀时代的降临》（高天无影1，2019.08–11） <a class="header-anchor" href="#_3-《黄金价格这么个玩法-意味着国际性大通胀时代的降临》-高天无影1-2019-08–11" aria-label="Permalink to &quot;3.《黄金价格这么个玩法，意味着国际性大通胀时代的降临》（高天无影1，2019.08–11）&quot;">​</a></h3><p><strong>核心论点</strong>：①地方与国企负债率高，中国无牌跟世界降息潮；②黄金大牛市（2018 年末即判断）；③&quot;汇市不破，房市无忧，股市无戏&quot;；④提出 2021 年岁尾布局 A 股。 <strong>金句</strong>：「汇市不破，房市无忧，股市无戏。」 <strong>→2026 检验：准。</strong> 2021–2022 全球大通胀如期而至，金价从 1500 涨向 3000 美元上方，是全合集最硬的宏观兑现之一；2021 底介入 A 股后虽有回撤，但 2024–2025 行情兑现&quot;台阶还得上&quot;。</p><h3 id="_4-《被抑制的通胀能捂多久》-天之星-涯钻天石之星-2019-02–12" tabindex="-1">4.《被抑制的通胀能捂多久》（天之星/涯钻天石之星，2019.02–12） <a class="header-anchor" href="#_4-《被抑制的通胀能捂多久》-天之星-涯钻天石之星-2019-02–12" aria-label="Permalink to &quot;4.《被抑制的通胀能捂多久》（天之星/涯钻天石之星，2019.02–12）&quot;">​</a></h3><p><strong>核心论点</strong>：①&quot;七年一个轮回&quot;，2019 曙光再现；②看多楼市，A 股&quot;一万点会到的&quot;；③大基建投资率超警戒线，效果微乎其微。 <strong>→2026 检验：不准。</strong> A 股未到一万点，楼市 2021 年后全国性下跌；&quot;被抑制的通胀&quot;倒是真捂了五年以上——但那是通缩式捂法，与其&quot;滞胀释放&quot;预设相反。属房多情绪贴。</p><h2 id="二、房地产-神贴与余波" tabindex="-1">二、房地产：神贴与余波 <a class="header-anchor" href="#二、房地产-神贴与余波" aria-label="Permalink to &quot;二、房地产：神贴与余波&quot;">​</a></h2><h3 id="_5-《2010-年的房地产调控-我们收获了什么-写在房价暴涨前》-kkndme-2010-08–2011-07" tabindex="-1">5.《2010 年的房地产调控，我们收获了什么？写在房价暴涨前》（kkndme，2010.08–2011.07） <a class="header-anchor" href="#_5-《2010-年的房地产调控-我们收获了什么-写在房价暴涨前》-kkndme-2010-08–2011-07" aria-label="Permalink to &quot;5.《2010 年的房地产调控，我们收获了什么？写在房价暴涨前》（kkndme，2010.08–2011.07）&quot;">​</a></h3><p><strong>核心论点</strong>：①房价由金字塔顶端&quot;精英平均收入&quot;决定，而非平均工资；②调控真实目的是中央收权——提门槛、清小开发商，让国家队垄断定价、垄断房租（公租房即伏笔）；③房产税几年内不会出，出了也向房租转嫁；④调控精准打击刚需，其首付和成本只会更高；⑤楼市若不再吸金，物价（蒜、姜、绿豆）会替它吸。 <strong>金句</strong>：「辨别利益是看透一切事物真相的武器。」「税收从来都是向下游转嫁的。」 <strong>→2026 检验：十年窗口内全准。</strong> 2015–2017 暴涨、房产税落空、公租房推进、限购限售成主工具、调控后蒜姜暴涨，逐一应验；&quot;精英收入定价&quot;甚至解释了 2020–2021 一线豪宅逆势上行。唯一未料的是 2021 年后人口与债务反噬使全国性下跌——框架建立在&quot;货币永续宽松+稀缺&quot;上，对收缩期失灵。</p><h3 id="_6-《周期的尾声来袭-这是百年一遇的机会》-时代之-2019-05–07" tabindex="-1">6.《周期的尾声来袭，这是百年一遇的机会》（时代之，2019.05–07） <a class="header-anchor" href="#_6-《周期的尾声来袭-这是百年一遇的机会》-时代之-2019-05–07" aria-label="Permalink to &quot;6.《周期的尾声来袭，这是百年一遇的机会》（时代之，2019.05–07）&quot;">​</a></h3><p><strong>核心论点</strong>：①债务危机四结局：做大分母、软着陆、通胀式破灭、通缩式破灭（资产负债表衰退）；②中国一季度又把杠杆加回去，软着陆无望；③房价五年内大概率下跌；④纳指 8000–8500 见&quot;三重大顶&quot;，可做空。 <strong>金句</strong>：「十次危机九次债，九次中又有七次是房地产。」 <strong>→2026 检验：半准半错。</strong> 房价 2021 见顶后连跌数年，判断准确；但纳指 2021–2025 从 8500 涨破 20000，做空美股是全合集最大打脸点之一。体制分析扎实，择时勇气过剩。</p><h2 id="三、年度与大周期预测" tabindex="-1">三、年度与大周期预测 <a class="header-anchor" href="#三、年度与大周期预测" aria-label="Permalink to &quot;三、年度与大周期预测&quot;">​</a></h2><h3 id="_7-《2019-趋势预测及机会分析》-老江南-2018-12–2019" tabindex="-1">7.《2019 趋势预测及机会分析》（老江南，2018.12–2019） <a class="header-anchor" href="#_7-《2019-趋势预测及机会分析》-老江南-2018-12–2019" aria-label="Permalink to &quot;7.《2019 趋势预测及机会分析》（老江南，2018.12–2019）&quot;">​</a></h3><p><strong>核心论点</strong>：①GDP 约 6.5%；②上证跌破 2449，区间震荡 1900–2900；③人民币有序贬到 8；④降准 2 次以上、不降息；⑤房产税不统一出台，房价结构分化：四五线暴跌烂尾、厦门大跌；⑥机会在 5G、物联网、新消费。 <strong>金句</strong>：「中国股市根本不是中国经济的晴雨表，而是韭菜收割机。」 <strong>→2026 检验：部分准。</strong> 降准节奏、跌破 2449、不征统一房产税、四五线烂尾与厦门回调全部应验；但汇率到 8、区间下沿 1900–2100、增速 6.5% 均过于悲观——方向感好，幅度感差。</p><h3 id="_8-《2018-2019-实现个人财富飞跃的重要关口》-高级工程狮a-2018-11–2019-02" tabindex="-1">8.《2018-2019，实现个人财富飞跃的重要关口》（高级工程狮A，2018.11–2019.02） <a class="header-anchor" href="#_8-《2018-2019-实现个人财富飞跃的重要关口》-高级工程狮a-2018-11–2019-02" aria-label="Permalink to &quot;8.《2018-2019，实现个人财富飞跃的重要关口》（高级工程狮A，2018.11–2019.02）&quot;">​</a></h3><p><strong>核心论点</strong>：①注册制（科创板）19 年到来，将重构股价；②持币、逢反弹减仓；③人民币升 6.4、热钱涌入；④燕郊触底反弹，房产仍适合全仓投入。 <strong>→2026 检验：部分准。</strong> 科创板 2019.07 落地、注册制重构估值（准）；&quot;持币&quot;此后两年跑赢（准）；但汇率、燕郊、热钱推高房股全落空，且 2019.02 末明显转多。</p><h3 id="_9-《纯预测贴-向底层的劳苦大众们献礼》-系统方法论-2018-07–12" tabindex="-1">9.《纯预测贴，向底层的劳苦大众们献礼》（系统方法论，2018.07–12） <a class="header-anchor" href="#_9-《纯预测贴-向底层的劳苦大众们献礼》-系统方法论-2018-07–12" aria-label="Permalink to &quot;9.《纯预测贴，向底层的劳苦大众们献礼》（系统方法论，2018.07–12）&quot;">​</a></h3><p><strong>核心论点</strong>：①经济危机已开始，&quot;危机的过程就是牛市的过程&quot;，机会在 19–20 年，20 年后一地鸡毛；②房价三年内崩盘；③房产税 2020 年前开征；④荐股铁龙物流&quot;目标 40 元&quot;。 <strong>→2026 检验：基本不准。</strong> 房产税未征、个股未涨；唯&quot;20 年后一地鸡毛&quot;歪打正着（2021 起走熊）。帖内充斥打赏引导与话术，属典型荐股引流帖。</p><h3 id="_10-《大格局-未来一年与十年-》-老仇乱侃-2019-02–05" tabindex="-1">10.《大格局：未来一年与十年！》（老仇乱侃，2019.02–05） <a class="header-anchor" href="#_10-《大格局-未来一年与十年-》-老仇乱侃-2019-02–05" aria-label="Permalink to &quot;10.《大格局：未来一年与十年！》（老仇乱侃，2019.02–05）&quot;">​</a></h3><p><strong>核心论点</strong>：①中国统一大市场=「工业粉碎机」，白菜价能力一路向上打穿中高端；②未来十年是巨头涌现期，普通人普惠式暴富机会消失；③2019–2020 进入通缩周期，现金为王、降杠杆、别在 2019 年按揭买房；④汽车、手机及传统制造出清，银行裁员、卖场倒闭；服务、家政、养老、5G、生物科技吸纳就业。 <strong>金句</strong>：「在经济扩张期努力加大杠杆，在经济收缩期努力降低杠杆，这是活在现代社会中必须学会的生存之道。」 <strong>→2026 检验：准。</strong> 通缩周期、车企手机业洗牌、字节/拼多多级巨头、养老家政就业崛起均兑现。老仇系列三帖（122/184/195）是全合集命中率最高的作者。</p><h3 id="_11-《2020-年-经济小酒醉一醉-重发版-》-老仇乱侃-2020-01–03" tabindex="-1">11.《2020 年，经济小酒醉一醉（重发版）》（老仇乱侃，2020.01–03） <a class="header-anchor" href="#_11-《2020-年-经济小酒醉一醉-重发版-》-老仇乱侃-2020-01–03" aria-label="Permalink to &quot;11.《2020 年，经济小酒醉一醉（重发版）》（老仇乱侃，2020.01–03）&quot;">​</a></h3><p><strong>核心论点</strong>：①出生率跳水将引发从尿布到房屋的连环需求不足，人口收缩城市扩大；②2020 就业更严峻，服务业红海；③民族自信爆棚将带起国潮；④房市&quot;蓄水池&quot;失效后，M2 溢出推高基础消费品；⑤3 月 1 日判断：全球经济将大回调，&quot;美股再上去就是做空好时机&quot;。 <strong>→2026 检验：准（含一次漂亮的择时）。</strong> 方向判断全部兑现；2020-03-01 发言一周后美股熔断式崩盘。</p><h3 id="_12-《人-应该怎么活-应该怎么赚钱-》-老仇乱侃-2019-01–02" tabindex="-1">12.《人，应该怎么活？应该怎么赚钱？》（老仇乱侃，2019.01–02） <a class="header-anchor" href="#_12-《人-应该怎么活-应该怎么赚钱-》-老仇乱侃-2019-01–02" aria-label="Permalink to &quot;12.《人，应该怎么活？应该怎么赚钱？》（老仇乱侃，2019.01–02）&quot;">​</a></h3><p><strong>核心论点</strong>：①炒股第一课是承认自己是&quot;屌丝&quot;：禀赋不可靠努力补偿，别学&quot;绝招&quot;；②不要与大多数人同思路；③普通人靠压缩开支攒本金+低效笨办法（拨档子年化 10%+）实现收入多元化；④避开电器、手机、汽车等传统制造红海。 <strong>金句</strong>：「承认自己是屌丝的背后，是这个世界上有智慧的人比例很低，而你大概率不在其中。」 <strong>→2026 检验：部分准。</strong> 属方法论而非预测；朴素反人性建议经 2019–2025 机构化行情验证有效。</p><h2 id="四、经济模式与宏观评论" tabindex="-1">四、经济模式与宏观评论 <a class="header-anchor" href="#四、经济模式与宏观评论" aria-label="Permalink to &quot;四、经济模式与宏观评论&quot;">​</a></h2><h3 id="_13-《大江论经济》-大江宁静-2018-03–07" tabindex="-1">13.《大江论经济》（大江宁静，2018.03–07） <a class="header-anchor" href="#_13-《大江论经济》-大江宁静-2018-03–07" aria-label="Permalink to &quot;13.《大江论经济》（大江宁静，2018.03–07）&quot;">​</a></h3><p><strong>核心论点</strong>：①中美贸易战打不起来，最终谈判妥协；②中国将转向内需为主，转型痛苦但必需；③房地产将被&quot;横盘冻结&quot;，靠 M2 增长以通胀消化泡沫；④房价以人民币计价难跌——政府可大放水、贬汇率来保；⑤六条建议：削出口退税、降物流成本、对等开放、各类企业平权、要素自由流通、少搞大基建。 <strong>金句</strong>：「肉在锅里，不怕你飞出去。」 <strong>→2026 检验：部分准。</strong> 转内需、限购冻结期（2018–2020）、基建收缩全对；但贸易战 2018.07 即开打并延续成科技战，&quot;房价人民币计价难跌&quot;在 2021 年后彻底失效——框架缺了&quot;土地财政终结&quot;这根支柱。</p><h3 id="_14-《经济模式和社会根源随想》-kulese-2018-03–2019-11" tabindex="-1">14.《经济模式和社会根源随想》（Kulese，2018.03–2019.11） <a class="header-anchor" href="#_14-《经济模式和社会根源随想》-kulese-2018-03–2019-11" aria-label="Permalink to &quot;14.《经济模式和社会根源随想》（Kulese，2018.03–2019.11）&quot;">​</a></h3><p><strong>核心论点</strong>：①凯恩斯主义/福利主义本质是政治赎买——花钱买稳定，不能解决危机只把问题往后拖；②中国是典型生产过剩模式，放水只会推资产价格、加剧贫富分化；③劳动力供给拐点已过，大拆大建模式注定走不下去；④政府失业率高企时必大规模放水；⑤&quot;任何断定房价涨跌的论断都太草率&quot;；⑥2019.11 判断 A 股仅是脉冲、2440 非牛市起点。 <strong>金句</strong>：「做投资最重要的就是要承认对未来的无知，把握那些能够把握的收益。」 <strong>→2026 检验：准。</strong> 基建到顶、流动性陷阱、&quot;危机时必放水&quot;（2024–2025 政策组合拳）全部应验；2440 非牛起点的判断被 2022–2024 二次探底证实。全合集逻辑质量最高的政经评论。</p><h3 id="_15-《资产价格极度扭曲-金融市场必有大事发生-》-邹艺湘-2017-12–2018-12" tabindex="-1">15.《资产价格极度扭曲，金融市场必有大事发生！》（邹艺湘，2017.12–2018.12） <a class="header-anchor" href="#_15-《资产价格极度扭曲-金融市场必有大事发生-》-邹艺湘-2017-12–2018-12" aria-label="Permalink to &quot;15.《资产价格极度扭曲，金融市场必有大事发生！》（邹艺湘，2017.12–2018.12）&quot;">​</a></h3><p><strong>核心论点</strong>：①估值铁律「企业的价值=未来十年盈利的总和」（&quot;十年回本&quot;）；②工行建行利润全球前二却打五折，迟早修复；③比亚迪&quot;技术+成本&quot;综合优势胜过特斯拉，唐二代上市即见效；④互联网泡沫将再破裂，多数网络股十年后市值腰斩；⑤每次资产价格极度扭曲必有震荡。 <strong>金句</strong>：「十年回本这个指标看似粗糙，在现实中非常靠谱，从不出错。」 <strong>→2026 检验：部分准。</strong> 震荡论（2018、2022）与比亚迪销量登顶应验；银行股 2024–2025 大涨但未&quot;翻倍式修复&quot;；互联网不跌反涨，是其在成长股上的系统性盲区。</p><h3 id="_16-《整个全球经济的怪现象》-独孤求败ah-2019-09" tabindex="-1">16.《整个全球经济的怪现象》（独孤求败AH，2019.09） <a class="header-anchor" href="#_16-《整个全球经济的怪现象》-独孤求败ah-2019-09" aria-label="Permalink to &quot;16.《整个全球经济的怪现象》（独孤求败AH，2019.09）&quot;">​</a></h3><p><strong>核心论点</strong>：①地球没有真市场经济，金字塔由军工—战略资源—民用—农业构成，中美收入差是&quot;航母的功劳&quot;；②2025 中美将因货币战争爆发巨大冲突；③中国和平崛起靠文化兴国。 <strong>→2026 检验：大部分不准。</strong> 中美对抗加剧方向对了，但归因停留在&quot;航母决定收入&quot;的阴谋论框架，未提技术、制度与要素生产率；&quot;美国十年内沦为二流&quot;亦未兑现。属情绪宣泄型经济帖。</p><h3 id="_17-《面对可能要到来的可怕滞涨-我们该怎么办-》-潜龙一生在渊-2017-10" tabindex="-1">17.《面对可能要到来的可怕滞涨，我们该怎么办？》（潜龙一生在渊，2017.10） <a class="header-anchor" href="#_17-《面对可能要到来的可怕滞涨-我们该怎么办-》-潜龙一生在渊-2017-10" aria-label="Permalink to &quot;17.《面对可能要到来的可怕滞涨，我们该怎么办？》（潜龙一生在渊，2017.10）&quot;">​</a></h3><p><strong>核心论点</strong>：①通胀=货币超发+成本推动（供给侧去产能、环保风暴推高生产资料）；②关键看成本能否传导至生活资料：能传则滞胀，不能传则复苏，约五六成 vs 四五成；③&quot;滞&quot;几乎注定，苦日子都要过；④建议保工作、降开支、减债。 <strong>金句</strong>：「滞，就是收入停滞甚至失业；胀，就是物价上涨，两头挨打才可怕。」 <strong>→2026 检验：部分准。</strong> 2018 猪周期短暂传导致 CPI 破 4，随后被需求塌陷扑灭；&quot;滞&quot;字 2019–2025 一语成谶，&quot;胀&quot;字落空。对普通人的防御清单至今适用。</p><h2 id="五、行业机会与见闻" tabindex="-1">五、行业机会与见闻 <a class="header-anchor" href="#五、行业机会与见闻" aria-label="Permalink to &quot;五、行业机会与见闻&quot;">​</a></h2><h3 id="_18-《寻找朝阳行业-为下一个五年、十年做储备》-李院士-2019-06–07" tabindex="-1">18.《寻找朝阳行业，为下一个五年、十年做储备》（李院士，2019.06–07） <a class="header-anchor" href="#_18-《寻找朝阳行业-为下一个五年、十年做储备》-李院士-2019-06–07" aria-label="Permalink to &quot;18.《寻找朝阳行业，为下一个五年、十年做储备》（李院士，2019.06–07）&quot;">​</a></h3><p><strong>核心论点</strong>：30 个方向重点点名：小众化/远程健身、个性化医疗、5G 与视频直播、自动驾驶、测评平台、垃圾分类千亿产业、植发、新农业（直播卖货、室内农场）、养老服务、为巨头做配套。 <strong>→2026 检验：部分准。</strong> 直播带货、植发、养老、服务大厂供应链大爆发；垃圾分类退潮、5G 雷声大雨点小、&quot;大教育产业&quot;被双减腰斩。成功率约六成，错在政策变量而非趋势判断——教育是最典型样本。</p><h3 id="_19-《放眼2023-2024-慢慢写我的见闻》-我就是ladisai-2017-06–2019-04" tabindex="-1">19.《放眼2023~2024，慢慢写我的见闻》（我就是ladisai，2017.06–2019.04） <a class="header-anchor" href="#_19-《放眼2023-2024-慢慢写我的见闻》-我就是ladisai-2017-06–2019-04" aria-label="Permalink to &quot;19.《放眼2023~2024，慢慢写我的见闻》（我就是ladisai，2017.06–2019.04）&quot;">​</a></h3><p><strong>核心论点</strong>：①美联储缩表+中国 M2 增速跌破 10%，&quot;勒紧裤带的时代&quot;到来，实体人从进攻转防守；②未来所有产业都会&quot;富士康化&quot;（代工化、巨头化）；③借推背图&quot;黑兔走入青龙穴&quot;指 2023–2024 为重大转折；④环保、安监、催款收紧是衰退的微观信号。 <strong>→2026 检验：部分准。</strong> 2017–2018 对实体收缩的微观记录极准；&quot;2023–2024 转折&quot;与地产出清、政策大转向的实际节点吻合。但主体是流水账，论证依赖卦辞，属&quot;记对了时代、算错了理由&quot;。</p><h3 id="_20-《西方社会心态变化》-海上京叔-2019-12–2020-04" tabindex="-1">20.《西方社会心态变化》（海上京叔，2019.12–2020.04） <a class="header-anchor" href="#_20-《西方社会心态变化》-海上京叔-2019-12–2020-04" aria-label="Permalink to &quot;20.《西方社会心态变化》（海上京叔，2019.12–2020.04）&quot;">​</a></h3><p><strong>核心论点</strong>：①美国硬件二十年间几乎未变，人心从九十年代的自信宽容变为焦虑不安；②中国供应链完备度是制造竞争力核心，制造业回流不可看好；③东南亚体量与效率不足以威胁中国制造；④脱欧争论未完，不排除苏格兰公投。 <strong>金句</strong>：「硬件变化不大，精神状态变化巨大。」 <strong>→2026 检验：准。</strong> &quot;西方集体心理转熊&quot;在 2020 后的民粹与保护主义中被充分验证；制造业回流至今停留在补贴建厂层面；苏格兰公投未成行（小错）。</p><h2 id="六、玄学命理类预测" tabindex="-1">六、玄学命理类预测 <a class="header-anchor" href="#六、玄学命理类预测" aria-label="Permalink to &quot;六、玄学命理类预测&quot;">​</a></h2><h3 id="_21-《形势转变中-未来哪些行业有前景》-庖丁医命0-2019-05–12" tabindex="-1">21.《形势转变中，未来哪些行业有前景》（庖丁医命0，2019.05–12） <a class="header-anchor" href="#_21-《形势转变中-未来哪些行业有前景》-庖丁医命0-2019-05–12" aria-label="Permalink to &quot;21.《形势转变中，未来哪些行业有前景》（庖丁医命0，2019.05–12）&quot;">​</a></h3><p><strong>核心论点</strong>：①未来十余年行&quot;火运&quot;：AI/数字化、文化教育、能源、军工有前景；②2019 土地经济仍是主旋律，政策全力保地产；③2020 庚子年有大劫；④2019.12 底预测美欧股市春节前后共振大跌。 <strong>→2026 检验：准（方法论存疑）。</strong> AI 与军工兑现、保地产延续到 2021、2020 疫情+美股春节后四次熔断，三连中。五行外壳无法证伪，但时点命中率反超多数技术派。</p><h3 id="_22-《拨开迷雾看未来》-庖丁医命0-2019-06–07" tabindex="-1">22.《拨开迷雾看未来》（庖丁医命0，2019.06–07） <a class="header-anchor" href="#_22-《拨开迷雾看未来》-庖丁医命0-2019-06–07" aria-label="Permalink to &quot;22.《拨开迷雾看未来》（庖丁医命0，2019.06–07）&quot;">​</a></h3><p><strong>核心论点</strong>：①国家如暴发户家庭：富裕—透支—衰退的轮回；②将经历衰退与高通胀交替的&quot;螺旋式下跌&quot;，社会资本持续消耗、再分配；③通缩是终点，但先经历漫长滞胀；④未来三十年走&quot;火运&quot;，唯&quot;人品&quot;可渡劫。 <strong>金句</strong>：「我们将经历长时间的经济衰退和民生物资高通胀交替发展的螺旋式下跌，几乎没有什么人能保住财富。」 <strong>→2026 检验：部分准。</strong> &quot;先滞胀后退&quot;的次序反了（直接进入需求塌陷式通缩），但&quot;多数人保不住财富&quot;（房价、理财、存款收益率全线下滑）应验。</p><h3 id="_23-《胡言乱语之虚空秘事》-小纯人-2019-04–2020-02" tabindex="-1">23.《胡言乱语之虚空秘事》（小纯人，2019.04–2020.02） <a class="header-anchor" href="#_23-《胡言乱语之虚空秘事》-小纯人-2019-04–2020-02" aria-label="Permalink to &quot;23.《胡言乱语之虚空秘事》（小纯人，2019.04–2020.02）&quot;">​</a></h3><p><strong>核心论点</strong>：灵界征文式幻想：自述元神统兵、与&quot;一贯道&quot;势力在虚空大战、守护华夏气运；2019 年 4 月预言&quot;人间战乱、灾荒、瘟疫即将开始&quot;。 <strong>→2026 检验：不可证伪。</strong> 无可检验的经济预测；&quot;瘟疫开始&quot;与 2020 疫情的时间巧合值得一提，但属文本开放性而非预测力，仅展示经济论坛边缘的神秘主义供给。</p><h3 id="_24-《如是我观-关注探讨的一些话题-》-北京毛毛-2006–2015" tabindex="-1">24.《如是我观（关注探讨的一些话题）》（北京毛毛，2006–2015） <a class="header-anchor" href="#_24-《如是我观-关注探讨的一些话题-》-北京毛毛-2006–2015" aria-label="Permalink to &quot;24.《如是我观（关注探讨的一些话题）》（北京毛毛，2006–2015）&quot;">​</a></h3><p><strong>核心论点</strong>：①2006 年即断言中国 2015 年后进入老龄化，养老金体系将承压、通胀难免；②全球流动性过剩，虚拟经济压过实体；③长期看好黄金至 2000 美元上方；④美联储持续升息将戳破美国房地产泡沫；⑤美元体系终将动荡，建议&quot;把资产折算成黄金来看&quot;；⑥2006 年 A 股持股别被洗出来。 <strong>金句</strong>：「把自己的资产折算成黄金来看——所有货币的购买力随时间递减，黄金的购买力相对固定。」 <strong>→2026 检验：大部分准。</strong> 黄金 2011 破 1900、2020 后长牛至 3000 美元上方；2008 次贷与 2006–2007 A 股牛均踩中；唯&quot;美元突然大贬值概率 100%&quot;落空。此帖是 2006 年语境下视野最超前的宏观评论，也是老龄化与黄金主线的最早源头。</p><hr><h2 id="总览与心得" tabindex="-1">总览与心得 <a class="header-anchor" href="#总览与心得" aria-label="Permalink to &quot;总览与心得&quot;">​</a></h2><p><strong>整体命中率（按&quot;方向—结构—点位&quot;三层计）约六成</strong>。</p><ul><li><strong>结构性判断（制度逻辑、人口、行业兴衰）最高，约 7–8 成</strong>：kkndme 的调控逻辑、老仇的通缩/巨头/人口三部曲、Kulese 的放水必然论、北京毛毛的老龄化与黄金，全部经受住了 2019–2025。</li><li><strong>方向性宏观（通胀 vs 通缩、汇率区间）约五成</strong>：大通胀派（169、199、165）只对了全球通胀那一半，对中国需求塌陷的那一半集体失明；汇率预测（贬到 8、升到 6.4/3）全军覆没——没人猜中&quot;横在 7&quot;这个最无聊的答案。</li><li><strong>点位与择时最低，约三成</strong>：上证 1900–2100、纳指 8500 见顶、A 股一万点、铁龙 40 元，无一兑现；唯一成功择时（老仇 2020-03-01 做空美股）更像周期认知加运气。</li></ul><p><strong>最容易准</strong>：①从利益结构和政策约束出发的推演（调控为收权、房产税难产、降准不加息、注册制节奏）——决策者选项集有限；②人口与代际长变量——周期以十年计，容错高；③猜&quot;什么东西会消失&quot;（普惠暴富、薄利多销、卖场）比猜&quot;什么会暴涨&quot;容易。</p><p><strong>最容易错</strong>：①给市场定具体点位、给汇率定终值；②把&quot;美国必衰/美元必崩&quot;当公理（196、164 的教训）；③把短期货币状态当永恒——kkndme&quot;房价以人民币计价难跌&quot;统治了十年，却在土地财政拐点处失效；④玄学模型方向感不差，但无法修正，时点一错全盘皆输。</p><p><strong>一句话总结</strong>：预测的核心竞争力不是模型，而是对&quot;谁在决策、他怕什么&quot;的理解；凡从利益与人出发的判断大多活到了 2026，凡从情绪与信仰出发的断言，大多留在了发帖那年。</p>',64)])])}const c=o(e,[["render",s]]);export{d as __pageData,c as default};
